```python
def bsearch(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
```

```python
def qsort(xs):
    if len(xs) <= 1:
        return xs
    p = xs[0]
    lo = [x for x in xs[1:] if x < p]
    hi = [x for x in xs[1:] if x >= p]
    return qsort(lo) + [p] + qsort(hi)
```

```python
def bubble(a):
    a = list(a)
    n = len(a)
    for i in range(n):
        for j in range(n - i - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
    return a
```

